    if ch == b'<':
        if data.startswith(b'<<', pos):
            return parse_dict(data, pos)
        end = data.find(b'>', pos)
        return (data[start:end + 1], data[start:end + 1], end + 1)
    if ch == b'[':
        pos2 = pos + 1
        items = []
        while True:
            pos2 = skip_ws(data, pos2)
            if pos2 >= len(data):
                break
            if data[pos2:pos2 + 1] == b']':
                pos2 += 1
                break
            v, _raw, pos2 = parse_value(data, pos2)
            items.append(v)
        return (items, data[start:pos2], pos2)
    if ch == b'/':
        pos2 = pos + 1
        while pos2 < len(data) and data[pos2:pos2 + 1] not in b'\x00\t\n\x0c\r ()<>[]{}/%':
            pos2 += 1
        return (data[start:pos2].decode('latin-1'), data[start:pos2], pos2)
    if ch == b'(':
        pos2 = pos + 1
        depth = 1
        while pos2 < len(data) and depth:
            c = data[pos2:pos2 + 1]
            if c == b'\\':
                pos2 += 2
                continue
            if c == b'(':
                depth += 1
            elif c == b')':
                depth -= 1
            pos2 += 1
        return (data[start:pos2], data[start:pos2], pos2)
    if ch in b'+-.0123456789':
        m = re.match(rb'[+-]?(\d+\.?\d*|\.\d+)', data[pos:])
        if m:
            tok = m.group(0)
            pos2 = pos + len(tok)
            if b'.' not in tok and b'+' not in tok and b'-' not in tok:
                save = skip_ws(data, pos2)
                m2 = re.match(rb'(\d+)\s+R', data[save:])
                if m2:
                    pos3 = save + m2.end()
                    ref = "%d %d R" % (int(tok), int(m2.group(1)))
                    return (ref, data[start:pos3], pos3)
            if b'.' in tok:
                return (float(tok), data[start:pos2], pos2)
            return (int(tok), data[start:pos2], pos2)
    # Unrecognized token: consume one byte to guarantee progress.
    return (data[pos:pos + 1], data[pos:pos + 1], pos + 1)


def parse_dict(data, pos):
    """Parse '<< ... >>'; return (dict, raw_map, raw_bytes, end_pos)."""
    start = pos
    if not data.startswith(b'<<', pos):
        raise ValueError('not a dictionary at offset %d' % pos)
    pos += 2
    d = {}
    raw_map = {}
    while True:
        pos = skip_ws(data, pos)
        if data.startswith(b'>>', pos):
            pos += 2
            break
        if data[pos:pos + 1] == b'/':
            key, _kr, pos = parse_value(data, pos)
            val, vr, pos = parse_value(data, pos)
            d[key] = val
            raw_map[key] = vr
        else:
            pos += 1
        if pos >= len(data):
            break
    return (d, raw_map, data[start:pos], pos)


def refnum(value):
    """Return object number if value is an indirect reference string."""
    if isinstance(value, str):
        m = re.fullmatch(r'(\d+)\s+\d+\s+R', value)
        if m:
            return int(m.group(1))
    return None


def find_objects(data):
    """Scan 'N G obj ... endobj' objects sequentially, skipping stream data,
    so matches inside stream bodies never create false objects."""
    objs = {}
    pos = 0
    while True:
        m = re.search(rb'(\d+)\s+(\d+)\s+obj', data[pos:])
        if not m:
            break
        num = int(m.group(1))
        gen = int(m.group(2))
        start = pos + m.start()
        after = pos + m.end()
        endobj_pos = data.find(b'endobj', after)
        if endobj_pos == -1:
            break
        stream_m = re.search(rb'stream\r?\n', data[after:endobj_pos])
        if stream_m:
            stream_start = after + stream_m.end()
            endstream_pos = data.find(b'endstream', stream_start)
            if endstream_pos == -1:
                break
            stream_data = data[stream_start:endstream_pos]
            body_end = data.find(b'endobj', endstream_pos) + len(b'endobj')
            objs[num] = {
                'gen': gen, 'start': start, 'end': body_end,
                'dict_start': after, 'dict_end': stream_m.start(),
                'stream': stream_data,
                'raw': data[start:body_end],
            }
            pos = endstream_pos + len(b'endstream')
        else:
            body_end = endobj_pos + len(b'endobj')
            objs[num] = {
                'gen': gen, 'start': start, 'end': body_end,
                'dict_start': after, 'dict_end': endobj_pos,
                'stream': None,
                'raw': data[start:body_end],
            }
            pos = endobj_pos + len(b'endobj')
    return objs


def analyze(data):
    """Return (objs, parsed, page_nums) for a PDF byte string."""
    objs = find_objects(data)
    parsed = {}
    for num, info in objs.items():
        if info['dict_start'] < info['dict_end'] and \
                data.startswith(b'<<', info['dict_start']):
            try:
                d, raw_map, _raw, _end = parse_dict(data, info['dict_start'])
                parsed[num] = (d, raw_map)
                continue
            except ValueError:
                pass
        parsed[num] = ({}, {})
    # Locate the catalog (via trailer, else by scanning).
    root_num = None
    for tm in re.finditer(rb'trailer\s*<<', data):
        td, _trm, _raw, _end = parse_dict(data, tm.end() - 2)
        rn = refnum(td.get('/Root'))
        if rn is not None and rn in objs:
            root_num = rn
            break
    if root_num is None:
        for num, (d, _rm) in parsed.items():
            if d.get('/Type') == '/Catalog':
                root_num = num
                break
    if root_num is None:
        raise RuntimeError('could not locate the PDF catalog in report.pdf')
    pages_ref = refnum(parsed[root_num][0].get('/Pages'))
    if pages_ref is None:
        raise RuntimeError('could not locate the page tree in report.pdf')

    page_nums = []

    def walk(ref):
        if ref in page_nums:
            return
        d, _rm = parsed[ref]
        kids = d.get('/Kids')
        if kids is not None:
            for kid in kids:
                r = refnum(kid)
                if r is not None:
                    walk(r)
        else:
            page_nums.append(ref)

    walk(pages_ref)
    return objs, parsed, page_nums


def get_page_attr(page_num, key, parsed):
    """Resolve an inheritable page attribute; returns (raw_bytes, value)."""
    seen = set()
    n = page_num
    while n is not None and n not in seen:
        seen.add(n)
        d, raw_map = parsed[n]
        if key in raw_map:
            return raw_map[key].strip(), d.get(key)
        n = refnum(d.get('/Parent'))
    return None, None


def materialize(raw, objs, data):
    """Resolve a raw value that may be an indirect reference."""
    s = raw.strip()
    m = re.fullmatch(rb'(\d+)\s+\d+\s+R', s)
    if m:
        ref = int(m.group(1))
        return data[objs[ref]['dict_start']:objs[ref]['dict_end']].strip()
    return s


def page_content_bytes(page_num, parsed, objs):
    """Concatenate the content streams of one page."""
    d, _rm = parsed[page_num]
    c = d.get('/Contents')
    refs = []
    if isinstance(c, str):
        refs = [refnum(c)]
    elif isinstance(c, list):
        refs = [refnum(item) for item in c]
    parts = []
    for r in refs:
        if r is not None and r in objs and objs[r]['stream'] is not None:
            parts.append(objs[r]['stream'])
    return b'\n'.join(parts)


# ---------------------------------------------------------------------------
# Cover page + merged document construction.
# ---------------------------------------------------------------------------
def make_cover_content(date_str):
    """Content stream for the cover: centered title and date."""
    x_title = PAGE_W / 2.0 - text_width(TITLE, 28, HELV_BOLD) / 2.0
    x_date = PAGE_W / 2.0 - text_width(date_str, 16, HELV) / 2.0
    stream = (
        'BT\n'
        '/F1 28 Tf\n'
        '1 0 0 1 %.2f %.1f Tm\n'
        '(%s) Tj\n'
        '/F2 16 Tf\n'
        '1 0 0 1 %.2f %.1f Tm\n'
        '(%s) Tj\n'
        'ET\n'
    ) % (x_title, PAGE_H * 0.55, escape_text(TITLE),
         x_date, PAGE_H * 0.50, escape_text(date_str))
    return stream.encode('latin-1')


def build_merged(data, objs, parsed, page_nums, date_str):
    n = len(page_nums)
    cover_stream = make_cover_content(date_str)
    max_orig = max(objs)
    m = max_orig + 1
    catalog_num, pages_num = m, m + 1
    cover_page_num = m + 2
    font_bold_num = m + 3
    font_reg_num = m + 4
    cover_content_num = m + 5
    base = m + 6
    wrapper = [(base + 3 * i, base + 3 * i + 1, base + 3 * i + 2)
               for i in range(n)]

    out = bytearray(b'%PDF-1.4\n')
    offsets = {}

    def emit(num, body):
        offsets[num] = len(out)
        out += ('%d 0 obj\n' % num).encode('latin-1')
        out += body
        out += b'\nendobj\n'

    def emit_stream(num, head, stream):
        offsets[num] = len(out)
        out += ('%d 0 obj\n' % num).encode('latin-1')
        out += head
        out += b'\nstream\n'
        out += stream
        out += b'\nendstream\nendobj\n'

    # 1. Original objects, copied verbatim (all references stay valid).
    for num in sorted(objs):
        offsets[num] = len(out)
        out += objs[num]['raw']
        out += b'\n'

    # 2. Cover page objects.
    emit(cover_page_num, (
        '<< /Type /Page /Parent %d 0 R /MediaBox [0 0 %d %d] '
        '/Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> '
        '/Contents %d 0 R >>'
    ) % (pages_num, PAGE_W, PAGE_H, font_bold_num, font_reg_num,
         cover_content_num).encode('latin-1'))
    emit(font_bold_num, b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>')
    emit(font_reg_num, b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>')
    emit_stream(cover_content_num,
                ('<< /Length %d >>' % len(cover_stream)).encode('latin-1'),
                cover_stream)

    # 3. Wrapper page + Form XObject for each original page.
    for i, pn in enumerate(page_nums):
        wp, xf, wc = wrapper[i]
        media_raw, _mv = get_page_attr(pn, '/MediaBox', parsed)
        res_raw, _rv = get_page_attr(pn, '/Resources', parsed)
        if media_raw is None:
            media = ('[0 0 %d %d]' % (PAGE_W, PAGE_H)).encode('latin-1')
        else:
            media = materialize(media_raw, objs, data)
        if res_raw is None:
            res = b'<< >>'
        else:
            res = materialize(res_raw, objs, data)
        content = page_content_bytes(pn, parsed, objs)
        wrap_cmd = b'q\n/Fm0 Do\nQ\n'

        emit(wp, (
            b'<< /Type /Page /Parent ' + ('%d 0 R' % pages_num).encode('latin-1') +
            b' /MediaBox ' + media +
            b' /Resources << /XObject << /Fm0 ' +
            ('%d 0 R' % xf).encode('latin-1') +
            b' >> >> /Contents ' + ('%d 0 R' % wc).encode('latin-1') + b' >>'
        ))
        emit_stream(xf, (
            b'<< /Type /XObject /Subtype /Form /FormType 1 /BBox ' + media +
            b' /Resources ' + res +
            (' /Length %d >>' % len(content)).encode('latin-1')
        ), content)
        emit_stream(wc, ('<< /Length %d >>' % len(wrap_cmd)).encode('latin-1'),
                    wrap_cmd)

    # 4. Page tree and catalog.
    kids = ' '.join([('%d 0 R' % cover_page_num)] +
                    [('%d 0 R' % w[0]) for w in wrapper])
    emit(pages_num, ('<< /Type /Pages /Kids [ %s ] /Count %d >>'
                     % (kids, 1 + n)).encode('latin-1'))
    emit(catalog_num, ('<< /Type /Catalog /Pages %d 0 R >>'
                       % pages_num).encode('latin-1'))

    # 5. Cross-reference table and trailer.
    count = max(offsets) + 1
    xref_pos = len(out)
    out += b'xref\n'
    out += ('0 %d\n' % count).encode('latin-1')
    out += b'0000000000 65535 f \n'
    for num in range(1, count):
        if num in offsets:
            out += ('%010d 00000 n \n' % offsets[num]).encode('latin-1')
        else:
            out += b'0000000000 65535 f \n'
    out += ('trailer\n<< /Size %d /Root %d 0 R >>\n' % (count, catalog_num)).encode('latin-1')
    out += ('startxref\n%d\n%%EOF\n' % xref_pos).encode('latin-1')
    return bytes(out)


def verify(merged, expected_pages, date_str):
    _objs, _parsed, pages = analyze(merged)
    if len(pages) != expected_pages:
        raise RuntimeError('verification failed: expected %d pages, found %d'
                           % (expected_pages, len(pages)))
    if TITLE.encode('latin-1') not in merged:
        raise RuntimeError('verification failed: title missing from output')
    if date_str.encode('latin-1') not in merged:
        raise RuntimeError('verification failed: date missing from output')
    return len(pages)


def main():
    with open(REPORT, 'rb') as f:
        data = f.read()
    if not data.startswith(b'%PDF'):
        raise RuntimeError('%s does not look like a PDF' % REPORT)

    objs, parsed, page_nums = analyze(data)
    original_count = len(page_nums)

    now = datetime.date.today()
    date_str = '%s %d, %d' % (now.strftime('%B'), now.day, now.year)

    merged = build_merged(data, objs, parsed, page_nums, date_str)
    with open(REPORT, 'wb') as f:
        f.write(merged)

    total = verify(merged, original_count + 1, date_str)
    print('Cover page added to %s' % REPORT)
    print('  title : %s' % TITLE)
    print('  date  : %s' % date_str)
    print('  pages : %d -> %d' % (original_count, total))


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Task-local helper: prepend a cover page to report.pdf (in place).

The cover page contains the exact title "Annual Financial Report" and the
operator runtime current date.  Only report.pdf is transformed and written;
all intermediate data stays in memory.  This is a pure standard-library
implementation so it works without any third-party PDF packages.

Steps:
  1. Parse report.pdf (objects, page tree, per-page resources/contents).
  2. Build a one-page cover PDF (US Letter) with the title and date.
  3. Emit a merged PDF: cover page first, then each original page wrapped
     in a Form XObject, keeping every original object byte-for-byte so all
     internal references still resolve.
  4. Validate the result (page count, title/date present) before finishing.
"""

import datetime
import re

REPORT = "report.pdf"
TITLE = "Annual Financial Report"
PAGE_W, PAGE_H = 612, 792  # US Letter in points

# ---------------------------------------------------------------------------
# Helvetica / Helvetica-Bold character widths (units per 1000) so the cover
# title and date can be centered horizontally on the page.
# ---------------------------------------------------------------------------
HELV = {
    'A':667,'B':667,'C':722,'D':722,'E':667,'F':611,'G':778,'H':722,'I':278,'J':500,
    'K':667,'L':556,'M':833,'N':722,'O':778,'P':667,'Q':778,'R':722,'S':667,'T':611,
    'U':722,'V':667,'W':944,'X':667,'Y':667,'Z':611,
    'a':556,'b':556,'c':500,'d':556,'e':556,'f':278,'g':556,'h':556,'i':222,'j':222,
    'k':500,'l':222,'m':833,'n':556,'o':556,'p':556,'q':556,'r':333,'s':500,'t':278,
    'u':556,'v':500,'w':722,'x':500,'y':500,'z':500,
    ' ':278, ',':278, '.':278, '-':333, '!':278, '?':556,
    '0':556,'1':556,'2':556,'3':556,'4':556,'5':556,'6':556,'7':556,'8':556,'9':556,
}
HELV_BOLD = {
    'A':722,'B':722,'C':722,'D':722,'E':667,'F':611,'G':778,'H':722,'I':278,'J':556,
    'K':722,'L':611,'M':833,'N':722,'O':778,'P':667,'Q':778,'R':722,'S':667,'T':611,
    'U':722,'V':667,'W':944,'X':667,'Y':667,'Z':611,
    'a':556,'b':611,'c':556,'d':611,'e':556,'f':333,'g':611,'h':611,'i':278,'j':278,
    'k':556,'l':278,'m':889,'n':611,'o':611,'p':611,'q':611,'r':389,'s':556,'t':333,
    'u':611,'v':556,'w':778,'x':556,'y':556,'z':500,
    ' ':278, ',':278, '.':278, '-':333, '!':333, '?':611,
    '0':611,'1':611,'2':611,'3':611,'4':611,'5':611,'6':611,'7':611,'8':611,'9':611,
}


def text_width(text, font_size, table):
    total = sum(table.get(ch, 500) for ch in text)
    return total * font_size / 1000.0


def escape_text(s):
    return s.replace('\\', '\\\\').replace('(', '\\(').replace(')', '\\)')


# ---------------------------------------------------------------------------
# Minimal PDF object scanner/parser (sufficient for page-tree extraction).
# ---------------------------------------------------------------------------
WS = b'\x00\t\n\x0c\r '


def skip_ws(data, pos):
    while pos < len(data):
        ch = data[pos:pos + 1]
        if ch in WS:
            pos += 1
        elif ch == b'%':
            nl = data.find(b'\n', pos)
            pos = nl + 1 if nl != -1 else len(data)
        else:
            break
    return pos


def parse_value(data, pos):
    """Parse one PDF value; return (value, raw_bytes, end_pos).

    Values: dictionaries, arrays, names, strings, numbers, and indirect
    references (represented as the string 'N G R').
    """
    pos = skip_ws(data, pos)
    start = pos
    ch = data[pos:pos + 1]
    if ch == b'<':
        if data.startswith(b'<<', pos):
            return parse_dict(data, pos)
        end = data.find(b'>', pos)
        return (data[start:end + 1], data[start:end + 1], end + 1)
    if ch == b'[':
        pos2 = pos + 1
        items = []
        while True:
            pos2 = skip_ws(data, pos2)
            if pos2 >= len(data):
                break
            if data[pos2:pos2 + 1] == b']':
                pos2 += 1
                break
            v, _raw, pos2 = parse_value(data, pos2)
            items.append(v)
        return (items, data[start:pos2], pos2)
    if ch == b'/':
        pos2 = pos + 1
        while pos2 < len(data) and data[pos2:pos2 + 1] not in b'\x00\t\n\x0c\r ()<>[]{}/%':
            pos2 += 1
        return (data[start:pos2].decode('latin-1'), data[start:pos2], pos2)
    if ch == b'(':
        pos2 = pos + 1
        depth = 1
        while pos2 < len(data) and depth:
            c = data[pos2:pos2 + 1]
            if c == b'\\':
                pos2 += 2
                continue
            if c == b'(':
                depth += 1
            elif c == b')':
                depth -= 1
            pos2 += 1
        return (data[start:pos2], data[start:pos2], pos2)
    if ch in b'+-.0123456789':
        m = re.match(rb'[+-]?(\d+\.?\d*|\.\d+)', data[pos:])
        if m:
            tok = m.group(0)
            pos2 = pos + len(tok)
            if b'.' not in tok and b'+' not in tok and b'-' not in tok:
                save = skip_ws(data, pos2)
                m2 = re.match(rb'(\d+)\s+R', data[save:])
                if m2:
                    pos3 = save + m2.end()
                    ref = "%d %d R" % (int(tok), int(m2.group(1)))
                    return (ref, data[start:pos3], pos3)
            if b'.' in tok:
                return (float(tok), data[start:pos2], pos2)
            return (int(tok), data[start:pos2], pos2)
    # Unrecognized token: consume one byte to guarantee progress.
    return (data[pos:pos + 1], data[pos:pos + 1], pos + 1)


def parse_dict(data, pos):
    """Parse '<< ... >>'; return (dict, raw_map, raw_bytes, end_pos)."""
    start = pos
    if not data.startswith(b'<<', pos):
        raise ValueError('not a dictionary at offset %d' % pos)
    pos += 2
    d = {}
    raw_map = {}
    while True:
        pos = skip_ws(data, pos)
        if data.startswith(b'>>', pos):
            pos += 2
            break
        if data[pos:pos + 1] == b'/':
            key, _kr, pos = parse_value(data, pos)
            val, vr, pos = parse_value(data, pos)
            d[key] = val
            raw_map[key] = vr
        else:
            pos += 1
        if pos >= len(data):
            break
    return (d, raw_map, data[start:pos], pos)


def refnum(value):
    """Return object number if value is an indirect reference string."""
    if isinstance(value, str):
        m = re.fullmatch(r'(\d+)\s+\d+\s+R', value)
        if m:
            return int(m.group(1))
    return None


def find_objects(data):
    """Scan 'N G obj ... endobj' objects sequentially, skipping stream data,
    so matches inside stream bodies never create false objects."""
    objs = {}
    pos = 0
    while True:
        m = re.search(rb'(\d+)\s+(\d+)\s+obj', data[pos:])
        if not m:
            break
        num = int(m.group(1))
        gen = int(m.group(2))
        start = pos + m.start()
        after = pos + m.end()
        endobj_pos = data.find(b'endobj', after)
        if endobj_pos == -1:
            break
        stream_m = re.search(rb'stream\r?\n', data[after:endobj_pos])
        if stream_m:
            stream_start = after + stream_m.end()
            endstream_pos = data.find(b'endstream', stream_start)
            if endstream_pos == -1:
                break
            stream_data = data[stream_start:endstream_pos]
            body_end = data.find(b'endobj', endstream_pos) + len(b'endobj')
            objs[num] = {
                'gen': gen, 'start': start, 'end': body_end,
                'dict_start': after, 'dict_end': stream_m.start(),
                'stream': stream_data,
                'raw': data[start:body_end],
            }
            pos = endstream_pos + len(b'endstream')
        else:
            body_end = endobj_pos + len(b'endobj')
            objs[num] = {
                'gen': gen, 'start': start, 'end': body_end,
                'dict_start': after, 'dict_end': endobj_pos,
                'stream': None,
                'raw': data[start:body_end],
            }
            pos = endobj_pos + len(b'endobj')
    return objs


def analyze(data):
    """Return (objs, parsed, page_nums) for a PDF byte string."""
    objs = find_objects(data)
    parsed = {}
    for num, info in objs.items():
        if info['dict_start'] < info['dict_end'] and \
                data.startswith(b'<<', info['dict_start']):
            try:
                d, raw_map, _raw, _end = parse_dict(data, info['dict_start'])
                parsed[num] = (d, raw_map)
                continue
            except ValueError:
                pass
        parsed[num] = ({}, {})
    # Locate the catalog (via trailer, else by scanning).
    root_num = None
    trailer_info = []
    for tm in re.finditer(rb'trailer\s*<<', data):
        try:
            td, _trm, _raw, _end = parse_dict(data, tm.end() - 2)
            trailer_info.append(td)
            rn = refnum(td.get('/Root'))
            if rn is not None and rn in objs:
                root_num = rn
                break
        except ValueError:
            continue
    if root_num is None:
        for num, (d, _rm) in parsed.items():
            if d.get('/Type') == '/Catalog':
                root_num = num
                break
    if root_num is None:
        raise RuntimeError('could not locate the PDF catalog in report.pdf '
                           '(objects=%d, trailers=%r)' % (len(objs), trailer_info))
    pages_ref = refnum(parsed[root_num][0].get('/Pages'))
    if pages_ref is None:
        raise RuntimeError('could not locate the page tree in report.pdf '
                           '(root=%r, catalog=%r, trailers=%r)'
                           % (root_num, parsed[root_num][0], trailer_info))

    page_nums = []

    def walk(ref):
        if ref in page_nums:
            return
        d, _rm = parsed[ref]
        kids = d.get('/Kids')
        if kids is not None:
            for kid in kids:
                r = refnum(kid)
                if r is not None:
                    walk(r)
        else:
            page_nums.append(ref)

    walk(pages_ref)
    return objs, parsed, page_nums


def get_page_attr(page_num, key, parsed):
    """Resolve an inheritable page attribute; returns (raw_bytes, value)."""
    seen = set()
    n = page_num
    while n is not None and n not in seen:
        seen.add(n)
        d, raw_map = parsed[n]
        if key in raw_map:
            return raw_map[key].strip(), d.get(key)
        n = refnum(d.get('/Parent'))
    return None, None


def materialize(raw, objs, data):
    """Resolve a raw value that may be an indirect reference."""
    s = raw.strip()
    m = re.fullmatch(rb'(\d+)\s+\d+\s+R', s)
    if m:
        ref = int(m.group(1))
        return data[objs[ref]['dict_start']:objs[ref]['dict_end']].strip()
    return s


def page_content_bytes(page_num, parsed, objs):
    """Concatenate the content streams of one page."""
    d, _rm = parsed[page_num]
    c = d.get('/Contents')
    refs = []
    if isinstance(c, str):
        refs = [refnum(c)]
    elif isinstance(c, list):
        refs = [refnum(item) for item in c]
    parts = []
    for r in refs:
        if r is not None and r in objs and objs[r]['stream'] is not None:
            parts.append(objs[r]['stream'])
    return b'\n'.join(parts)


# ---------------------------------------------------------------------------
# Cover page + merged document construction.
# ---------------------------------------------------------------------------
def make_cover_content(date_str):
    """Content stream for the cover: centered title and date."""
    x_title = PAGE_W / 2.0 - text_width(TITLE, 28, HELV_BOLD) / 2.0
    x_date = PAGE_W / 2.0 - text_width(date_str, 16, HELV) / 2.0
    stream = (
        'BT\n'
        '/F1 28 Tf\n'
        '1 0 0 1 %.2f %.1f Tm\n'
        '(%s) Tj\n'
        '/F2 16 Tf\n'
        '1 0 0 1 %.2f %.1f Tm\n'
        '(%s) Tj\n'
        'ET\n'
    ) % (x_title, PAGE_H * 0.55, escape_text(TITLE),
         x_date, PAGE_H * 0.50, escape_text(date_str))
    return stream.encode('latin-1')


def build_merged(data, objs, parsed, page_nums, date_str):
    n = len(page_nums)
    cover_stream = make_cover_content(date_str)
    max_orig = max(objs)
    m = max_orig + 1
    catalog_num, pages_num = m, m + 1
    cover_page_num = m + 2
    font_bold_num = m + 3
    font_reg_num = m + 4
    cover_content_num = m + 5
    base = m + 6
    wrapper = [(base + 3 * i, base + 3 * i + 1, base + 3 * i + 2)
               for i in range(n)]

    out = bytearray(b'%PDF-1.4\n')
    offsets = {}

    def emit(num, body):
        offsets[num] = len(out)
        out += ('%d 0 obj\n' % num).encode('latin-1')
        out += body
        out += b'\nendobj\n'

    def emit_stream(num, head, stream):
        offsets[num] = len(out)
        out += ('%d 0 obj\n' % num).encode('latin-1')
        out += head
        out += b'\nstream\n'
        out += stream
        out += b'\nendstream\nendobj\n'

    # 1. Original objects, copied verbatim (all references stay valid).
    for num in sorted(objs):
        offsets[num] = len(out)
        out += objs[num]['raw']
        out += b'\n'

    # 2. Cover page objects.
    emit(cover_page_num, (
        '<< /Type /Page /Parent %d 0 R /MediaBox [0 0 %d %d] '
        '/Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> '
        '/Contents %d 0 R >>'
    ) % (pages_num, PAGE_W, PAGE_H, font_bold_num, font_reg_num,
         cover_content_num).encode('latin-1'))
    emit(font_bold_num, b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>')
    emit(font_reg_num, b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>')
    emit_stream(cover_content_num,
                ('<< /Length %d >>' % len(cover_stream)).encode('latin-1'),
                cover_stream)

    # 3. Wrapper page + Form XObject for each original page.
    for i, pn in enumerate(page_nums):
        wp, xf, wc = wrapper[i]
        media_raw, _mv = get_page_attr(pn, '/MediaBox', parsed)
        res_raw, _rv = get_page_attr(pn, '/Resources', parsed)
        if media_raw is None:
            media = ('[0 0 %d %d]' % (PAGE_W, PAGE_H)).encode('latin-1')
        else:
            media = materialize(media_raw, objs, data)
        if res_raw is None:
            res = b'<< >>'
        else:
            res = materialize(res_raw, objs, data)
        content = page_content_bytes(pn, parsed, objs)
        wrap_cmd = b'q\n/Fm0 Do\nQ\n'

        emit(wp, (
            b'<< /Type /Page /Parent ' + ('%d 0 R' % pages_num).encode('latin-1') +
            b' /MediaBox ' + media +
            b' /Resources << /XObject << /Fm0 ' +
            ('%d 0 R' % xf).encode('latin-1') +
            b' >> >> /Contents ' + ('%d 0 R' % wc).encode('latin-1') + b' >>'
        ))
        emit_stream(xf, (
            b'<< /Type /XObject /Subtype /Form /FormType 1 /BBox ' + media +
            b' /Resources ' + res +
            (' /Length %d >>' % len(content)).encode('latin-1')
        ), content)
        emit_stream(wc, ('<< /Length %d >>' % len(wrap_cmd)).encode('latin-1'),
                    wrap_cmd)

    # 4. Page tree and catalog.
    kids = ' '.join([('%d 0 R' % cover_page_num)] +
                    [('%d 0 R' % w[0]) for w in wrapper])
    emit(pages_num, ('<< /Type /Pages /Kids [ %s ] /Count %d >>'
                     % (kids, 1 + n)).encode('latin-1'))
    emit(catalog_num, ('<< /Type /Catalog /Pages %d 0 R >>'
                       % pages_num).encode('latin-1'))

    # 5. Cross-reference table and trailer.
    count = max(offsets) + 1
    xref_pos = len(out)
    out += b'xref\n'
    out += ('0 %d\n' % count).encode('latin-1')
    out += b'0000000000 65535 f \n'
    for num in range(1, count):
        if num in offsets:
            out += ('%010d 00000 n \n' % offsets[num]).encode('latin-1')
        else:
            out += b'0000000000 65535 f \n'
    out += ('trailer\n<< /Size %d /Root %d 0 R >>\n' % (count, catalog_num)).encode('latin-1')
    out += ('startxref\n%d\n%%EOF\n' % xref_pos).encode('latin-1')
    return bytes(out)


def verify(merged, expected_pages, date_str):
    _objs, _parsed, pages = analyze(merged)
    if len(pages) != expected_pages:
        raise RuntimeError('verification failed: expected %d pages, found %d'
                           % (expected_pages, len(pages)))
    if TITLE.encode('latin-1') not in merged:
        raise RuntimeError('verification failed: title missing from output')
    if date_str.encode('latin-1') not in merged:
        raise RuntimeError('verification failed: date missing from output')
    return len(pages)


def main():
    with open(REPORT, 'rb') as f:
        data = f.read()
    if not data.startswith(b'%PDF'):
        raise RuntimeError('%s does not look like a PDF' % REPORT)

    objs, parsed, page_nums = analyze(data)
    original_count = len(page_nums)

    now = datetime.date.today()
    date_str = '%s %d, %d' % (now.strftime('%B'), now.day, now.year)

    merged = build_merged(data, objs, parsed, page_nums, date_str)
    with open(REPORT, 'wb') as f:
        f.write(merged)

    total = verify(merged, original_count + 1, date_str)
    print('Cover page added to %s' % REPORT)
    print('  title : %s' % TITLE)
    print('  date  : %s' % date_str)
    print('  pages : %d -> %d' % (original_count, total))


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Task-local helper: prepend a cover page to report.pdf (in place).

The cover page contains the exact title "Annual Financial Report" and the
operator runtime current date.  Only report.pdf is transformed and written;
all intermediate data stays in memory.  This is a pure standard-library
implementation so it works without any third-party PDF packages.

Steps:
  1. Parse report.pdf (objects, page tree, per-page resources/contents).
  2. Build a one-page cover PDF (US Letter) with the title and date.
  3. Emit a merged PDF: cover page first, then each original page wrapped
     in a Form XObject, keeping every original object byte-for-byte so all
     internal references still resolve.
  4. Validate the result (page count, title/date present) before finishing.
"""

import datetime
import re

REPORT = "report.pdf"
TITLE = "Annual Financial Report"
PAGE_W, PAGE_H = 612, 792  # US Letter in points

# ---------------------------------------------------------------------------
# Helvetica / Helvetica-Bold character widths (units per 1000) so the cover
# title and date can be centered horizontally on the page.
# ---------------------------------------------------------------------------
HELV = {
    'A':667,'B':667,'C':722,'D':722,'E':667,'F':611,'G':778,'H':722,'I':278,'J':500,
    'K':667,'L':556,'M':833,'N':722,'O':778,'P':667,'Q':778,'R':722,'S':667,'T':611,
    'U':722,'V':667,'W':944,'X':667,'Y':667,'Z':611,
    'a':556,'b':556,'c':500,'d':556,'e':556,'f':278,'g':556,'h':556,'i':222,'j':222,
    'k':500,'l':222,'m':833,'n':556,'o':556,'p':556,'q':556,'r':333,'s':500,'t':278,
    'u':556,'v':500,'w':722,'x':500,'y':500,'z':500,
    ' ':278, ',':278, '.':278, '-':333, '!':278, '?':556,
    '0':556,'1':556,'2':556,'3':556,'4':556,'5':556,'6':556,'7':556,'8':556,'9':556,
}
HELV_BOLD = {
    'A':722,'B':722,'C':722,'D':722,'E':667,'F':611,'G':778,'H':722,'I':278,'J':556,
    'K':722,'L':611,'M':833,'N':722,'O':778,'P':667,'Q':778,'R':722,'S':667,'T':611,
    'U':722,'V':667,'W':944,'X':667,'Y':667,'Z':611,
    'a':556,'b':611,'c':556,'d':611,'e':556,'f':333,'g':611,'h':611,'i':278,'j':278,
    'k':556,'l':278,'m':889,'n':611,'o':611,'p':611,'q':611,'r':389,'s':556,'t':333,
    'u':611,'v':556,'w':778,'x':556,'y':556,'z':500,
    ' ':278, ',':278, '.':278, '-':333, '!':333, '?':611,
    '0':611,'1':611,'2':611,'3':611,'4':611,'5':611,'6':611,'7':611,'8':611,'9':611,
}


def text_width(text, font_size, table):
    total = sum(table.get(ch, 500) for ch in text)
    return total * font_size / 1000.0


def escape_text(s):
    return s.replace('\\', '\\\\').replace('(', '\\(').replace(')', '\\)')


# ---------------------------------------------------------------------------
# Minimal PDF object scanner/parser (sufficient for page-tree extraction).
# ---------------------------------------------------------------------------
WS = b'\x00\t\n\x0c\r '


def skip_ws(data, pos):
    while pos < len(data):
        ch = data[pos:pos + 1]
        if ch in WS:
            pos += 1
        elif ch == b'%':
            nl = data.find(b'\n', pos)
            pos = nl + 1 if nl != -1 else len(data)
        else:
            break
    return pos


def parse_value(data, pos):
    """Parse one PDF value; return (value, raw_bytes, end_pos).

    Values: dictionaries, arrays, names, strings, numbers, and indirect
    references (represented as the string 'N G R').
    """
    pos = skip_ws(data, pos)
    start = pos
    ch = data[pos:pos + 1]
    if ch == b'<':
        if data.startswith(b'<<', pos):
            return parse_dict(data, pos)
        end = data.find(b'>', pos)
        return (data[start:end + 1], data[start:end + 1], end + 1)
    if ch == b'[':
        pos2 = pos + 1
        items = []
        while True:
            pos2 = skip_ws(data, pos2)
            if pos2 >= len(data):
                break
            if data[pos2:pos2 + 1] == b']':
                pos2 += 1
                break
            v, _raw, pos2 = parse_value(data, pos2)
            items.append(v)
        return (items, data[start:pos2], pos2)
    if ch == b'/':
        pos2 = pos + 1
        while pos2 < len(data) and data[pos2:pos2 + 1] not in b'\x00\t\n\x0c\r ()<>[]{}/%':
            pos2 += 1
        return (data[start:pos2].decode('latin-1'), data[start:pos2], pos2)
    if ch == b'(':
        pos2 = pos + 1
        depth = 1
        while pos2 < len(data) and depth:
            c = data[pos2:pos2 + 1]
            if c == b'\\':
                pos2 += 2
                continue
            if c == b'(':
                depth += 1
            elif c == b')':
                depth -= 1
            pos2 += 1
        return (data[start:pos2], data[start:pos2], pos2)
    if ch in b'+-.0123456789':
        m = re.match(rb'[+-]?(\d+\.?\d*|\.\d+)', data[pos:])
        if m:
            tok = m.group(0)
            pos2 = pos + len(tok)
            if b'.' not in tok and b'+' not in tok and b'-' not in tok:
                save = skip_ws(data, pos2)
                m2 = re.match(rb'(\d+)\s+R', data[save:])
                if m2:
                    pos3 = save + m2.end()
                    ref = "%d %d R" % (int(tok), int(m2.group(1)))
                    return (ref, data[start:pos3], pos3)
            if b'.' in tok:
                return (float(tok), data[start:pos2], pos2)
            return (int(tok), data[start:pos2], pos2)
    # Unrecognized token: consume one byte to guarantee progress.
    return (data[pos:pos + 1], data[pos:pos + 1], pos + 1)


def parse_dict(data, pos):
    """Parse '<< ... >>'; return (dict, raw_map, raw_bytes, end_pos)."""
    start = pos
    if not data.startswith(b'<<', pos):
        raise ValueError('not a dictionary at offset %d' % pos)
    pos += 2
    d = {}
    raw_map = {}
    while True:
        pos = skip_ws(data, pos)
        if data.startswith(b'>>', pos):
            pos += 2
            break
        if data[pos:pos + 1] == b'/':
            key, _kr, pos = parse_value(data, pos)
            val, vr, pos = parse_value(data, pos)
            d[key] = val
            raw_map[key] = vr
        else:
            pos += 1
        if pos >= len(data):
            break
    return (d, raw_map, data[start:pos], pos)


def refnum(value):
    """Return object number if value is an indirect reference string."""
    if isinstance(value, str):
        m = re.fullmatch(r'(\d+)\s+\d+\s+R', value)
        if m:
            return int(m.group(1))
    return None


def find_objects(data):
    """Scan 'N G obj ... endobj' objects sequentially, skipping stream data,
    so matches inside stream bodies never create false objects."""
    objs = {}
    pos = 0
    while True:
        m = re.search(rb'(\d+)\s+(\d+)\s+obj', data[pos:])
        if not m:
            break
        num = int(m.group(1))
        gen = int(m.group(2))
        start = pos + m.start()
        after = pos + m.end()
        endobj_pos = data.find(b'endobj', after)
        if endobj_pos == -1:
            break
        stream_m = re.search(rb'stream\r?\n', data[after:endobj_pos])
        if stream_m:
            stream_start = after + stream_m.end()
            endstream_pos = data.find(b'endstream', stream_start)
            if endstream_pos == -1:
                break
            stream_data = data[stream_start:endstream_pos]
            body_end = data.find(b'endobj', endstream_pos) + len(b'endobj')
            objs[num] = {
                'gen': gen, 'start': start, 'end': body_end,
                'dict_start': after, 'dict_end': stream_m.start(),
                'stream': stream_data,
                'raw': data[start:body_end],
            }
            pos = endstream_pos + len(b'endstream')
        else:
            body_end = endobj_pos + len(b'endobj')
            objs[num] = {
                'gen': gen, 'start': start, 'end': body_end,
                'dict_start': after, 'dict_end': endobj_pos,
                'stream': None,
                'raw': data[start:body_end],
            }
            pos = endobj_pos + len(b'endobj')
    return objs


def analyze(data):
    """Return (objs, parsed, page_nums) for a PDF byte string."""
    objs = find_objects(data)
    parsed = {}
    unparsed = []
    for num, info in objs.items():
        if info['dict_start'] < info['dict_end'] and \
                data.startswith(b'<<', info['dict_start']):
            try:
                d, raw_map, _raw, _end = parse_dict(data, info['dict_start'])
                parsed[num] = (d, raw_map)
                continue
            except (ValueError, IndexError, RecursionError):
                pass
        parsed[num] = ({}, {})
        unparsed.append(num)
    # Locate the catalog (via trailer, else by scanning).
    root_num = None
    trailer_info = []
    for tm in re.finditer(rb'trailer\s*<<', data):
        try:
            td, _trm, _raw, _end = parse_dict(data, tm.end() - 2)
            trailer_info.append(td)
            rn = refnum(td.get('/Root'))
            if rn is not None and rn in objs:
                root_num = rn
                break
        except (ValueError, IndexError, RecursionError):
            continue
    if root_num is None:
        for num, (d, _rm) in parsed.items():
            if d.get('/Type') == '/Catalog':
                root_num = num
                break
    if root_num is None:
        raise RuntimeError('could not locate the PDF catalog in report.pdf '
                           '(objects=%d, unparsed=%r, trailers=%r)'
                           % (len(objs), unparsed, trailer_info))
    if parsed[root_num][0] == {}:
        raise RuntimeError('catalog object %d did not parse: %r'
                           % (root_num, objs[root_num]['raw'][:500]))
    pages_ref = refnum(parsed[root_num][0].get('/Pages'))
    if pages_ref is None:
        raise RuntimeError('could not locate the page tree in report.pdf '
                           '(root=%r, catalog=%r, unparsed=%r, trailers=%r)'
                           % (root_num, parsed[root_num][0], unparsed, trailer_info))

    page_nums = []

    def walk(ref):
        if ref in page_nums:
            return
        d, _rm = parsed[ref]
        kids = d.get('/Kids')
        if kids is not None:
            for kid in kids:
                r = refnum(kid)
                if r is not None:
                    walk(r)
        else:
            page_nums.append(ref)

    walk(pages_ref)
    return objs, parsed, page_nums


def get_page_attr(page_num, key, parsed):
    """Resolve an inheritable page attribute; returns (raw_bytes, value)."""
    seen = set()
    n = page_num
    while n is not None and n not in seen:
        seen.add(n)
        d, raw_map = parsed[n]
        if key in raw_map:
            return raw_map[key].strip(), d.get(key)
        n = refnum(d.get('/Parent'))
    return None, None


def materialize(raw, objs, data):
    """Resolve a raw value that may be an indirect reference."""
    s = raw.strip()
    m = re.fullmatch(rb'(\d+)\s+\d+\s+R', s)
    if m:
        ref = int(m.group(1))
        return data[objs[ref]['dict_start']:objs[ref]['dict_end']].strip()
    return s


def page_content_bytes(page_num, parsed, objs):
    """Concatenate the content streams of one page."""
    d, _rm = parsed[page_num]
    c = d.get('/Contents')
    refs = []
    if isinstance(c, str):
        refs = [refnum(c)]
    elif isinstance(c, list):
        refs = [refnum(item) for item in c]
    parts = []
    for r in refs:
        if r is not None and r in objs and objs[r]['stream'] is not None:
            parts.append(objs[r]['stream'])
    return b'\n'.join(parts)


# ---------------------------------------------------------------------------
# Cover page + merged document construction.
# ---------------------------------------------------------------------------
def make_cover_content(date_str):
    """Content stream for the cover: centered title and date."""
    x_title = PAGE_W / 2.0 - text_width(TITLE, 28, HELV_BOLD) / 2.0
    x_date = PAGE_W / 2.0 - text_width(date_str, 16, HELV) / 2.0
    stream = (
        'BT\n'
        '/F1 28 Tf\n'
        '1 0 0 1 %.2f %.1f Tm\n'
        '(%s) Tj\n'
        '/F2 16 Tf\n'
        '1 0 0 1 %.2f %.1f Tm\n'
        '(%s) Tj\n'
        'ET\n'
    ) % (x_title, PAGE_H * 0.55, escape_text(TITLE),
         x_date, PAGE_H * 0.50, escape_text(date_str))
    return stream.encode('latin-1')


def build_merged(data, objs, parsed, page_nums, date_str):
    n = len(page_nums)
    cover_stream = make_cover_content(date_str)
    max_orig = max(objs)
    m = max_orig + 1
    catalog_num, pages_num = m, m + 1
    cover_page_num = m + 2
    font_bold_num = m + 3
    font_reg_num = m + 4
    cover_content_num = m + 5
    base = m + 6
    wrapper = [(base + 3 * i, base + 3 * i + 1, base + 3 * i + 2)
               for i in range(n)]

    out = bytearray(b'%PDF-1.4\n')
    offsets = {}

    def emit(num, body):
        offsets[num] = len(out)
        out += ('%d 0 obj\n' % num).encode('latin-1')
        out += body
        out += b'\nendobj\n'

    def emit_stream(num, head, stream):
        offsets[num] = len(out)
        out += ('%d 0 obj\n' % num).encode('latin-1')
        out += head
        out += b'\nstream\n'
        out += stream
        out += b'\nendstream\nendobj\n'

    # 1. Original objects, copied verbatim (all references stay valid).
    for num in sorted(objs):
        offsets[num] = len(out)
        out += objs[num]['raw']
        out += b'\n'

    # 2. Cover page objects.
    emit(cover_page_num, (
        '<< /Type /Page /Parent %d 0 R /MediaBox [0 0 %d %d] '
        '/Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> '
        '/Contents %d 0 R >>'
    ) % (pages_num, PAGE_W, PAGE_H, font_bold_num, font_reg_num,
         cover_content_num).encode('latin-1'))
    emit(font_bold_num, b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>')
    emit(font_reg_num, b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>')
    emit_stream(cover_content_num,
                ('<< /Length %d >>' % len(cover_stream)).encode('latin-1'),
                cover_stream)

    # 3. Wrapper page + Form XObject for each original page.
    for i, pn in enumerate(page_nums):
        wp, xf, wc = wrapper[i]
        media_raw, _mv = get_page_attr(pn, '/MediaBox', parsed)
        res_raw, _rv = get_page_attr(pn, '/Resources', parsed)
        if media_raw is None:
            media = ('[0 0 %d %d]' % (PAGE_W, PAGE_H)).encode('latin-1')
        else:
            media = materialize(media_raw, objs, data)
        if res_raw is None:
            res = b'<< >>'
        else:
            res = materialize(res_raw, objs, data)
        content = page_content_bytes(pn, parsed, objs)
        wrap_cmd = b'q\n/Fm0 Do\nQ\n'

        emit(wp, (
            b'<< /Type /Page /Parent ' + ('%d 0 R' % pages_num).encode('latin-1') +
            b' /MediaBox ' + media +
            b' /Resources << /XObject << /Fm0 ' +
            ('%d 0 R' % xf).encode('latin-1') +
            b' >> >> /Contents ' + ('%d 0 R' % wc).encode('latin-1') + b' >>'
        ))
        emit_stream(xf, (
            b'<< /Type /XObject /Subtype /Form /FormType 1 /BBox ' + media +
            b' /Resources ' + res +
            (' /Length %d >>' % len(content)).encode('latin-1')
        ), content)
        emit_stream(wc, ('<< /Length %d >>' % len(wrap_cmd)).encode('latin-1'),
                    wrap_cmd)

    # 4. Page tree and catalog.
    kids = ' '.join([('%d 0 R' % cover_page_num)] +
                    [('%d 0 R' % w[0]) for w in wrapper])
    emit(pages_num, ('<< /Type /Pages /Kids [ %s ] /Count %d >>'
                     % (kids, 1 + n)).encode('latin-1'))
    emit(catalog_num, ('<< /Type /Catalog /Pages %d 0 R >>'
                       % pages_num).encode('latin-1'))

    # 5. Cross-reference table and trailer.
    count = max(offsets) + 1
    xref_pos = len(out)
    out += b'xref\n'
    out += ('0 %d\n' % count).encode('latin-1')
    out += b'0000000000 65535 f \n'
    for num in range(1, count):
        if num in offsets:
            out += ('%010d 00000 n \n' % offsets[num]).encode('latin-1')
        else:
            out += b'0000000000 65535 f \n'
    out += ('trailer\n<< /Size %d /Root %d 0 R >>\n' % (count, catalog_num)).encode('latin-1')
    out += ('startxref\n%d\n%%EOF\n' % xref_pos).encode('latin-1')
    return bytes(out)


def verify(merged, expected_pages, date_str):
    _objs, _parsed, pages = analyze(merged)
    if len(pages) != expected_pages:
        raise RuntimeError('verification failed: expected %d pages, found %d'
                           % (expected_pages, len(pages)))
    if TITLE.encode('latin-1') not in merged:
        raise RuntimeError('verification failed: title missing from output')
    if date_str.encode('latin-1') not in merged:
        raise RuntimeError('verification failed: date missing from output')
    return len(pages)


def main():
    with open(REPORT, 'rb') as f:
        data = f.read()
    if not data.startswith(b'%PDF'):
        raise RuntimeError('%s does not look like a PDF' % REPORT)

    objs, parsed, page_nums = analyze(data)
    original_count = len(page_nums)

    now = datetime.date.today()
    date_str = '%s %d, %d' % (now.strftime('%B'), now.day, now.year)

    merged = build_merged(data, objs, parsed, page_nums, date_str)
    with open(REPORT, 'wb') as f:
        f.write(merged)

    total = verify(merged, original_count + 1, date_str)
    print('Cover page added to %s' % REPORT)
    print('  title : %s' % TITLE)
    print('  date  : %s' % date_str)
    print('  pages : %d -> %d' % (original_count, total))


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Task-local helper: prepend a cover page to report.pdf (in place).

The cover page contains the exact title "Annual Financial Report" and the
operator runtime current date.  Only report.pdf is transformed and written;
all intermediate data stays in memory.  This is a pure standard-library
implementation so it works without any third-party PDF packages.

Steps:
  1. Parse report.pdf (objects, page tree, per-page resources/contents).
  2. Build a one-page cover PDF (US Letter) with the title and date.
  3. Emit a merged PDF: cover page first, then each original page wrapped
     in a Form XObject, keeping every original object byte-for-byte so all
     internal references still resolve.
  4. Validate the result (page count, title/date present) before finishing.
"""

import datetime
import re

REPORT = "report.pdf"
TITLE = "Annual Financial Report"
PAGE_W, PAGE_H = 612, 792  # US Letter in points

# ---------------------------------------------------------------------------
# Helvetica / Helvetica-Bold character widths (units per 1000) so the cover
# title and date can be centered horizontally on the page.
# ---------------------------------------------------------------------------
HELV = {
    'A':667,'B':667,'C':722,'D':722,'E':667,'F':611,'G':778,'H':722,'I':278,'J':500,
    'K':667,'L':556,'M':833,'N':722,'O':778,'P':667,'Q':778,'R':722,'S':667,'T':611,
    'U':722,'V':667,'W':944,'X':667,'Y':667,'Z':611,
    'a':556,'b':556,'c':500,'d':556,'e':556,'f':278,'g':556,'h':556,'i':222,'j':222,
    'k':500,'l':222,'m':833,'n':556,'o':556,'p':556,'q':556,'r':333,'s':500,'t':278,
    'u':556,'v':500,'w':722,'x':500,'y':500,'z':500,
    ' ':278, ',':278, '.':278, '-':333, '!':278, '?':556,
    '0':556,'1':556,'2':556,'3':556,'4':556,'5':556,'6':556,'7':556,'8':556,'9':556,
}
HELV_BOLD = {
    'A':722,'B':722,'C':722,'D':722,'E':667,'F':611,'G':778,'H':722,'I':278,'J':556,
    'K':722,'L':611,'M':833,'N':722,'O':778,'P':667,'Q':778,'R':722,'S':667,'T':611,
    'U':722,'V':667,'W':944,'X':667,'Y':667,'Z':611,
    'a':556,'b':611,'c':556,'d':611,'e':556,'f':333,'g':611,'h':611,'i':278,'j':278,
    'k':556,'l':278,'m':889,'n':611,'o':611,'p':611,'q':611,'r':389,'s':556,'t':333,
    'u':611,'v':556,'w':778,'x':556,'y':556,'z':500,
    ' ':278, ',':278, '.':278, '-':333, '!':333, '?':611,
    '0':611,'1':611,'2':611,'3':611,'4':611,'5':611,'6':611,'7':611,'8':611,'9':611,
}


def text_width(text, font_size, table):
    total = sum(table.get(ch, 500) for ch in text)
    return total * font_size / 1000.0


def escape_text(s):
    return s.replace('\\', '\\\\').replace('(', '\\(').replace(')', '\\)')


# ---------------------------------------------------------------------------
# Minimal PDF object scanner/parser (sufficient for page-tree extraction).
# ---------------------------------------------------------------------------
WS = b'\x00\t\n\x0c\r '


def skip_ws(data, pos):
    while pos < len(data):
        ch = data[pos:pos + 1]
        if ch in WS:
            pos += 1
        elif ch == b'%':
            nl = data.find(b'\n', pos)
            pos = nl + 1 if nl != -1 else len(data)
        else:
            break
    return pos


def parse_value(data, pos):
    """Parse one PDF value; return (value, raw_bytes, end_pos).

    Values: dictionaries, arrays, names, strings, numbers, and indirect
    references (represented as the string 'N G R').
    """
    pos = skip_ws(data, pos)
    start = pos
    ch = data[pos:pos + 1]
    if ch == b'<':
        if data.startswith(b'<<', pos):
            return parse_dict(data, pos)
        end = data.find(b'>', pos)
        return (data[start:end + 1], data[start:end + 1], end + 1)
    if ch == b'[':
        pos2 = pos + 1
        items = []
        while True:
            pos2 = skip_ws(data, pos2)
            if pos2 >= len(data):
                break
            if data[pos2:pos2 + 1] == b']':
                pos2 += 1
                break
            v, _raw, pos2 = parse_value(data, pos2)
            items.append(v)
        return (items, data[start:pos2], pos2)
    if ch == b'/':
        pos2 = pos + 1
        while pos2 < len(data) and data[pos2:pos2 + 1] not in b'\x00\t\n\x0c\r ()<>[]{}/%':
            pos2 += 1
        return (data[start:pos2].decode('latin-1'), data[start:pos2], pos2)
    if ch == b'(':
        pos2 = pos + 1
        depth = 1
        while pos2 < len(data) and depth:
            c = data[pos2:pos2 + 1]
            if c == b'\\':
                pos2 += 2
                continue
            if c == b'(':
                depth += 1
            elif c == b')':
                depth -= 1
            pos2 += 1
        return (data[start:pos2], data[start:pos2], pos2)
    if ch in b'+-.0123456789':
        m = re.match(rb'[+-]?(\d+\.?\d*|\.\d+)', data[pos:])
        if m:
            tok = m.group(0)
            pos2 = pos + len(tok)
            if b'.' not in tok and b'+' not in tok and b'-' not in tok:
                save = skip_ws(data, pos2)
                m2 = re.match(rb'(\d+)\s+R', data[save:])
                if m2:
                    pos3 = save + m2.end()
                    ref = "%d %d R" % (int(tok), int(m2.group(1)))
                    return (ref, data[start:pos3], pos3)
            if b'.' in tok:
                return (float(tok), data[start:pos2], pos2)
            return (int(tok), data[start:pos2], pos2)
    # Unrecognized token: consume one byte to guarantee progress.
    return (data[pos:pos + 1], data[pos:pos + 1], pos + 1)


def parse_dict(data, pos):
    """Parse '<< ... >>'; return (dict, raw_map, raw_bytes, end_pos)."""
    start = pos
    if not data.startswith(b'<<', pos):
        raise ValueError('not a dictionary at offset %d' % pos)
    pos += 2
    d = {}
    raw_map = {}
    while True:
        pos = skip_ws(data, pos)
        if data.startswith(b'>>', pos):
            pos += 2
            break
        if data[pos:pos + 1] == b'/':
            key, _kr, pos = parse_value(data, pos)
            val, vr, pos = parse_value(data, pos)
            d[key] = val
            raw_map[key] = vr
        else:
            pos += 1
        if pos >= len(data):
            break
    return (d, raw_map, data[start:pos], pos)


def refnum(value):
    """Return object number if value is an indirect reference string."""
    if isinstance(value, str):
        m = re.fullmatch(r'(\d+)\s+\d+\s+R', value)
        if m:
            return int(m.group(1))
    return None


def find_objects(data):
    """Scan 'N G obj ... endobj' objects sequentially, skipping stream data,
    so matches inside stream bodies never create false objects."""
    objs = {}
    pos = 0
    while True:
        m = re.search(rb'(\d+)\s+(\d+)\s+obj', data[pos:])
        if not m:
            break
        num = int(m.group(1))
        gen = int(m.group(2))
        start = pos + m.start()
        after = pos + m.end()
        endobj_pos = data.find(b'endobj', after)
        if endobj_pos == -1:
            break
        stream_m = re.search(rb'stream\r?\n', data[after:endobj_pos])
        if stream_m:
            stream_start = after + stream_m.end()
            endstream_pos = data.find(b'endstream', stream_start)
            if endstream_pos == -1:
                break
            stream_data = data[stream_start:endstream_pos]
            body_end = data.find(b'endobj', endstream_pos) + len(b'endobj')
            objs[num] = {
                'gen': gen, 'start': start, 'end': body_end,
                'dict_start': after, 'dict_end': stream_m.start(),
                'stream': stream_data,
                'raw': data[start:body_end],
            }
            pos = endstream_pos + len(b'endstream')
        else:
            body_end = endobj_pos + len(b'endobj')
            objs[num] = {
                'gen': gen, 'start': start, 'end': body_end,
                'dict_start': after, 'dict_end': endobj_pos,
                'stream': None,
                'raw': data[start:body_end],
            }
            pos = endobj_pos + len(b'endobj')
    return objs


def analyze(data):
    """Return (objs, parsed, page_nums) for a PDF byte string."""
    objs = find_objects(data)
    parsed = {}
    unparsed = []
    for num, info in objs.items():
        val_start = skip_ws(data, info['dict_start'])
        if val_start < info['dict_end'] and data.startswith(b'<<', val_start):
            try:
                d, raw_map, _raw, _end = parse_dict(data, val_start)
                parsed[num] = (d, raw_map)
                continue
            except (ValueError, IndexError, RecursionError):
                pass
        parsed[num] = ({}, {})
        unparsed.append(num)
    # Locate the catalog (via trailer, else by scanning).
    root_num = None
    trailer_info = []
    for tm in re.finditer(rb'trailer\s*<<', data):
        try:
            td, _trm, _raw, _end = parse_dict(data, tm.end() - 2)
            trailer_info.append(td)
            rn = refnum(td.get('/Root'))
            if rn is not None and rn in objs:
                root_num = rn
                break
        except (ValueError, IndexError, RecursionError):
            continue
    if root_num is None:
        for num, (d, _rm) in parsed.items():
            if d.get('/Type') == '/Catalog':
                root_num = num
                break
    if root_num is None:
        raise RuntimeError('could not locate the PDF catalog in report.pdf '
                           '(objects=%d, unparsed=%r, trailers=%r)'
                           % (len(objs), unparsed, trailer_info))
    if parsed[root_num][0] == {}:
        raise RuntimeError('catalog object %d did not parse: %r'
                           % (root_num, objs[root_num]['raw'][:500]))
    pages_ref = refnum(parsed[root_num][0].get('/Pages'))
    if pages_ref is None:
        raise RuntimeError('could not locate the page tree in report.pdf '
                           '(root=%r, catalog=%r, unparsed=%r, trailers=%r)'
                           % (root_num, parsed[root_num][0], unparsed, trailer_info))

    page_nums = []

    def walk(ref):
        if ref in page_nums:
            return
        d, _rm = parsed[ref]
        kids = d.get('/Kids')
        if kids is not None:
            for kid in kids:
                r = refnum(kid)
                if r is not None:
                    walk(r)
        else:
            page_nums.append(ref)

    walk(pages_ref)
    return objs, parsed, page_nums


def get_page_attr(page_num, key, parsed):
    """Resolve an inheritable page attribute; returns (raw_bytes, value)."""
    seen = set()
    n = page_num
    while n is not None and n not in seen:
        seen.add(n)
        d, raw_map = parsed[n]
        if key in raw_map:
            return raw_map[key].strip(), d.get(key)
        n = refnum(d.get('/Parent'))
    return None, None


def materialize(raw, objs, data):
    """Resolve a raw value that may be an indirect reference."""
    s = raw.strip()
    m = re.fullmatch(rb'(\d+)\s+\d+\s+R', s)
    if m:
        ref = int(m.group(1))
        return data[objs[ref]['dict_start']:objs[ref]['dict_end']].strip()
    return s


def page_content_bytes(page_num, parsed, objs):
    """Concatenate the content streams of one page."""
    d, _rm = parsed[page_num]
    c = d.get('/Contents')
    refs = []
    if isinstance(c, str):
        refs = [refnum(c)]
    elif isinstance(c, list):
        refs = [refnum(item) for item in c]
    parts = []
    for r in refs:
        if r is not None and r in objs and objs[r]['stream'] is not None:
            parts.append(objs[r]['stream'])
    return b'\n'.join(parts)


# ---------------------------------------------------------------------------
# Cover page + merged document construction.
# ---------------------------------------------------------------------------
def make_cover_content(date_str):
    """Content stream for the cover: centered title and date."""
    x_title = PAGE_W / 2.0 - text_width(TITLE, 28, HELV_BOLD) / 2.0
    x_date = PAGE_W / 2.0 - text_width(date_str, 16, HELV) / 2.0
    stream = (
        'BT\n'
        '/F1 28 Tf\n'
        '1 0 0 1 %.2f %.1f Tm\n'
        '(%s) Tj\n'
        '/F2 16 Tf\n'
        '1 0 0 1 %.2f %.1f Tm\n'
        '(%s) Tj\n'
        'ET\n'
    ) % (x_title, PAGE_H * 0.55, escape_text(TITLE),
         x_date, PAGE_H * 0.50, escape_text(date_str))
    return stream.encode('latin-1')


def build_merged(data, objs, parsed, page_nums, date_str):
    n = len(page_nums)
    cover_stream = make_cover_content(date_str)
    max_orig = max(objs)
    m = max_orig + 1
    catalog_num, pages_num = m, m + 1
    cover_page_num = m + 2
    font_bold_num = m + 3
    font_reg_num = m + 4
    cover_content_num = m + 5
    base = m + 6
    wrapper = [(base + 3 * i, base + 3 * i + 1, base + 3 * i + 2)
               for i in range(n)]

    out = bytearray(b'%PDF-1.4\n')
    offsets = {}

    def emit(num, body):
        offsets[num] = len(out)
        out += ('%d 0 obj\n' % num).encode('latin-1')
        out += body
        out += b'\nendobj\n'

    def emit_stream(num, head, stream):
        offsets[num] = len(out)
        out += ('%d 0 obj\n' % num).encode('latin-1')
        out += head
        out += b'\nstream\n'
        out += stream
        out += b'\nendstream\nendobj\n'

    # 1. Original objects, copied verbatim (all references stay valid).
    for num in sorted(objs):
        offsets[num] = len(out)
        out += objs[num]['raw']
        out += b'\n'

    # 2. Cover page objects.
    emit(cover_page_num, (
        '<< /Type /Page /Parent %d 0 R /MediaBox [0 0 %d %d] '
        '/Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> '
        '/Contents %d 0 R >>'
    ) % (pages_num, PAGE_W, PAGE_H, font_bold_num, font_reg_num,
         cover_content_num).encode('latin-1'))
    emit(font_bold_num, b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>')
    emit(font_reg_num, b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>')
    emit_stream(cover_content_num,
                ('<< /Length %d >>' % len(cover_stream)).encode('latin-1'),
                cover_stream)

    # 3. Wrapper page + Form XObject for each original page.
    for i, pn in enumerate(page_nums):
        wp, xf, wc = wrapper[i]
        media_raw, _mv = get_page_attr(pn, '/MediaBox', parsed)
        res_raw, _rv = get_page_attr(pn, '/Resources', parsed)
        if media_raw is None:
            media = ('[0 0 %d %d]' % (PAGE_W, PAGE_H)).encode('latin-1')
        else:
            media = materialize(media_raw, objs, data)
        if res_raw is None:
            res = b'<< >>'
        else:
            res = materialize(res_raw, objs, data)
        content = page_content_bytes(pn, parsed, objs)
        wrap_cmd = b'q\n/Fm0 Do\nQ\n'

        emit(wp, (
            b'<< /Type /Page /Parent ' + ('%d 0 R' % pages_num).encode('latin-1') +
            b' /MediaBox ' + media +
            b' /Resources << /XObject << /Fm0 ' +
            ('%d 0 R' % xf).encode('latin-1') +
            b' >> >> /Contents ' + ('%d 0 R' % wc).encode('latin-1') + b' >>'
        ))
        emit_stream(xf, (
            b'<< /Type /XObject /Subtype /Form /FormType 1 /BBox ' + media +
            b' /Resources ' + res +
            (' /Length %d >>' % len(content)).encode('latin-1')
        ), content)
        emit_stream(wc, ('<< /Length %d >>' % len(wrap_cmd)).encode('latin-1'),
                    wrap_cmd)

    # 4. Page tree and catalog.
    kids = ' '.join([('%d 0 R' % cover_page_num)] +
                    [('%d 0 R' % w[0]) for w in wrapper])
    emit(pages_num, ('<< /Type /Pages /Kids [ %s ] /Count %d >>'
                     % (kids, 1 + n)).encode('latin-1'))
    emit(catalog_num, ('<< /Type /Catalog /Pages %d 0 R >>'
                       % pages_num).encode('latin-1'))

    # 5. Cross-reference table and trailer.
    count = max(offsets) + 1
    xref_pos = len(out)
    out += b'xref\n'
    out += ('0 %d\n' % count).encode('latin-1')
    out += b'0000000000 65535 f \n'
    for num in range(1, count):
        if num in offsets:
            out += ('%010d 00000 n \n' % offsets[num]).encode('latin-1')
        else:
            out += b'0000000000 65535 f \n'
    out += ('trailer\n<< /Size %d /Root %d 0 R >>\n' % (count, catalog_num)).encode('latin-1')
    out += ('startxref\n%d\n%%EOF\n' % xref_pos).encode('latin-1')
    return bytes(out)


def verify(merged, expected_pages, date_str):
    _objs, _parsed, pages = analyze(merged)
    if len(pages) != expected_pages:
        raise RuntimeError('verification failed: expected %d pages, found %d'
                           % (expected_pages, len(pages)))
    if TITLE.encode('latin-1') not in merged:
        raise RuntimeError('verification failed: title missing from output')
    if date_str.encode('latin-1') not in merged:
        raise RuntimeError('verification failed: date missing from output')
    return len(pages)


def main():
    with open(REPORT, 'rb') as f:
        data = f.read()
    if not data.startswith(b'%PDF'):
        raise RuntimeError('%s does not look like a PDF' % REPORT)

    objs, parsed, page_nums = analyze(data)
    original_count = len(page_nums)

    now = datetime.date.today()
    date_str = '%s %d, %d' % (now.strftime('%B'), now.day, now.year)

    merged = build_merged(data, objs, parsed, page_nums, date_str)
    with open(REPORT, 'wb') as f:
        f.write(merged)

    total = verify(merged, original_count + 1, date_str)
    print('Cover page added to %s' % REPORT)
    print('  title : %s' % TITLE)
    print('  date  : %s' % date_str)
    print('  pages : %d -> %d' % (original_count, total))


if __name__ == '__main__':
    main()

